 BEGIN TRANSACTION;
CREATE TABLE web_events (
	id int,
	account_id int,
	occurred_at date,
	channel nvarchar(max)
);
CREATE TABLE sales_reps (
	id int,
	name nvarchar(max),
	region_id int
);
CREATE TABLE region (
	id int,
	name nvarchar(max)
);
CREATE TABLE orders (
	id int,
	account_id int,
	occurred_at date,
	standard_qty int,
	gloss_qty int,
	poster_qty int,
	total int,
	standard_amt_usd numeric(10,2),
	gloss_amt_usd numeric(10,2),
	poster_amt_usd numeric(10,2),
	total_amt_usd numeric(10,2)
);
CREATE TABLE accounts (
	id int,
	name nvarchar(max),
	website nvarchar(max),
	lat numeric(11,8),
	long numeric(11,8),
	primary_poc nvarchar(max),
	sales_rep_id int
);
COMMIT;
